def expand(query, llm):
    # one need -> several complementary search queries
    return llm(f"Give 3 diverse search queries for: {query}").splitlines()

variants = expand("how do I cancel and get refunded?", llm)
# ['how to cancel a subscription', 'refund policy after cancellation',
#  'prorated charges on cancellation']
hits = []
for q in variants:
    hits += vector_store.search(q, k=5)
chunks = dedupe(hits)               # union of facets -> better coverage

