# your code runs the retrieval and returns chunks as the observation

def agentic_rag(question, agent, max_steps=4):
    notes = []
    for _ in range(max_steps):
        action = agent.decide(question, notes)   # search again or answer?
        if action.type == "answer":
            return action.text
        chunks = vector_store.search(action.query, k=5)  # retrieve
        notes.append((action.query, chunks))     # read + remember
    return agent.answer(question, notes)          # step cap reached

