def rewrite_query(history, raw):
    # stub for an LLM rewrite: resolve 'it' to the last named entity
    entity = None
    for turn in history:
        for candidate in ["Pro plan", "Basic plan", "Enterprise plan"]:
            if candidate.lower() in turn.lower():
                entity = candidate
    if entity and " it " in f" {raw} ":
        return raw.replace("it", entity)
    return raw

history = ["Tell me about the Pro plan.", "How much is it?"]
raw = "does it include SSO?"
standalone = rewrite_query(history, raw)
print("raw:", raw)
print("rewritten:", standalone)
# the rewritten query now carries 'Pro plan', which the index can match

CORPUS = {
    "plans": "The Pro plan includes SSO. Basic does not.",
    "pricing": "Pro is $20/mo. A competitor charges $30/mo.",
}

def search(query):
    # naive keyword retrieval over a tiny corpus
    return [CORPUS[k] for k in CORPUS if any(w in CORPUS[k].lower() for w in query.lower().split())]

def policy(question, notes):
    # decide: what to search next, or answer when we have both facts
    have = " ".join(t for _, chunks in notes for t in chunks).lower()
    if "sso" not in have:
        return ("search", "which plan includes SSO")
    if "$" not in have:
        return ("search", "Pro plan price vs competitor")
    return ("answer", "Pro includes SSO at $20/mo, cheaper than the $30 competitor.")

def agentic_rag(question, max_steps=4):
    notes = []
    for _ in range(max_steps):
        kind, arg = policy(question, notes)
        if kind == "answer":
            return arg
        notes.append((arg, search(arg)))   # retrieve + remember
    return "insufficient context"

print(agentic_rag("Which plan has SSO and is it cheaper than the competitor?"))
